"""Exact optional three-shape VAE input packing integration."""
ORIGINAL='                for (int64_t offset=0; offset<ne01; offset+=spatial_block) {\n                    const int64_t width=std::min<int64_t>(spatial_block,ne01-offset);\n                    cblas_sgemm(CblasRowMajor,CblasNoTrans,CblasTrans,\n                        ne1,width,ne10,1.0f,y,ne10,x+offset*ne00,ne00,0.0f,d+offset,ne01);\n                }'
REPLACEMENT='                const char* packed_flag=std::getenv("SD_NLC_VAE_PRETRANSPOSE");\n                const bool pretranspose=packed_flag && std::strcmp(packed_flag,"1")==0 &&\n                    ((ne1==512 && ne01==16384 && ne10==4608 && spatial_block==2048) ||\n                     (ne1==256 && ne01==65536 && (ne10==2304 || ne10==4608) && spatial_block==4096));\n                std::unique_ptr<float,decltype(&std::free)> packed(\n                    pretranspose ? static_cast<float*>(std::malloc(size_t(spatial_block)*size_t(ne10)*sizeof(float))) : nullptr,\n                    &std::free);\n                if(pretranspose && !packed) throw std::runtime_error("VAE packing allocation failed");\n                for (int64_t offset=0; offset<ne01; offset+=spatial_block) {\n                    const int64_t width=std::min<int64_t>(spatial_block,ne01-offset);\n                    if(pretranspose) {\n                        if(!sd_ve_gemm_pack_f32(packed.get(),x+offset*ne00,int(width),int(ne10)))\n                            throw std::runtime_error("VAE packing contract failed");\n                        cblas_sgemm(CblasRowMajor,CblasNoTrans,CblasNoTrans,\n                            ne1,width,ne10,1.0f,y,ne10,packed.get(),width,0.0f,d+offset,ne01);\n                    } else {\n                        cblas_sgemm(CblasRowMajor,CblasNoTrans,CblasTrans,\n                            ne1,width,ne10,1.0f,y,ne10,x+offset*ne00,ne00,0.0f,d+offset,ne01);\n                    }\n                }\n                if(pretranspose) std::fprintf(stderr,"SD_NLC_PRETRANSPOSE stage=vae m=%lld n=%lld k=%lld tile=%lld calls=%lld bytes=%zu\\n",\n                    (long long)ne1,(long long)ne01,(long long)ne10,(long long)spatial_block,\n                    (long long)((ne01+spatial_block-1)/spatial_block),size_t(spatial_block)*size_t(ne10)*sizeof(float));'
def instrument(text):
    if text.count(ORIGINAL)!=1:raise RuntimeError("one frozen spatial-loop block required")
    return '#include <memory>\nextern "C" int sd_ve_gemm_pack_f32(float*,const float*,int,int);\n'+text.replace(ORIGINAL,REPLACEMENT)
